def relay_target_bursts(changes: list[int], target: int) -> int:
    counts = {0: 1}
    prefix = 0
    answer = 0
    for change in changes:
        prefix += change
        answer += counts.get(prefix - target, 0)
        counts[prefix] = counts.get(prefix, 0) + 1
    return answer

bruteForceSolution:
def relay_target_bursts(changes: list[int], target: int) -> int:
    answer = 0
    for start in range(len(changes)):
        total = 0
        for end in range(start, len(changes)):
            total += changes[end]
            if total == target:
                answer += 1
    return answer
